import{_ as o,o as e,c as t,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Contratos & OpenAPI 3.1","description":"","frontmatter":{},"headers":[],"relativePath":"pt-br/04-contratos-e-openapi.md","filePath":"pt-br/04-contratos-e-openapi.md"}'),i={name:"pt-br/04-contratos-e-openapi.md"};function s(r,a,p,d,c,l){return e(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="contratos-openapi-3-1" tabindex="-1">Contratos &amp; OpenAPI 3.1 <a class="header-anchor" href="#contratos-openapi-3-1" aria-label="Permalink to &quot;Contratos &amp; OpenAPI 3.1&quot;">​</a></h1><blockquote><p><strong>Sincronização Tipada de Ponta a Ponta</strong><br><em>FastAPI, Pydantic v2, Orval e TanStack Query.</em></p></blockquote><hr><h2 id="_1-fonte-unica-da-verdade" tabindex="-1">1. Fonte Única da Verdade <a class="header-anchor" href="#_1-fonte-unica-da-verdade" aria-label="Permalink to &quot;1. Fonte Única da Verdade&quot;">​</a></h2><p>No SoftForge, o frontend nunca cria tipos manuais ou URLs &quot;chumbadas&quot;. Toda a comunicação é baseada no contrato <strong>OpenAPI 3.1.0</strong> gerado automaticamente a partir dos modelos Pydantic v2 do FastAPI.</p><hr><h2 id="_2-extracao-estatica-a-frio-export-openapi-py" tabindex="-1">2. Extração Estática a Frio (<code>export_openapi.py</code>) <a class="header-anchor" href="#_2-extracao-estatica-a-frio-export-openapi-py" aria-label="Permalink to &quot;2. Extração Estática a Frio (`export_openapi.py`)&quot;">​</a></h2><p>Em frameworks tradicionais, para exportar a especificação OpenAPI você precisa rodar a API, subir banco de dados e bater em <code>http://localhost:8000/openapi.json</code>.</p><p>No SoftForge, o script <code>tools/scripts/export_openapi.py</code> extrai a especificação completa <strong>a frio</strong>, em menos de 1 segundo, instanciando o objeto FastAPI diretamente com banco mockado:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/export_openapi.py</span></span></code></pre></div><p>Isso gera o arquivo <code>apps/api/openapi.json</code>.</p><hr><h2 id="_3-geracao-automatica-de-hooks-no-frontend-orval" tabindex="-1">3. Geração Automática de Hooks no Frontend (<code>Orval</code>) <a class="header-anchor" href="#_3-geracao-automatica-de-hooks-no-frontend-orval" aria-label="Permalink to &quot;3. Geração Automática de Hooks no Frontend (`Orval`)&quot;">​</a></h2><p>Com o <code>openapi.json</code> gerado, você executa o Orval dentro de <code>apps/web</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codegen</span></span></code></pre></div><p>O Orval gera:</p><ul><li>Modelos TypeScript 100% tipados em <code>apps/web/src/api/generated/models/</code>.</li><li>Hooks do TanStack Query (<code>useQuery</code>, <code>useMutation</code>) para cada endpoint da API.</li><li>Configuração automática do cliente Axios com cookies HttpOnly e interceptors.</li></ul><p>Se o backend alterar o tipo de um campo ou remover um endpoint, o comando <code>npm run typecheck</code> no frontend falhará imediatamente no build, prevenindo qualquer bug em produção antes do commit!</p>',18)])])}const m=o(i,[["render",s]]);export{u as __pageData,m as default};
